function hydratePart(part: (typeof STYLED_COMPONENT_SEEDS)[number]['parts'][number], valueType?: string) {
  const valueProp = valueType
    ? { required: true, type: valueType, description: 'Stable collection key used to resolve this repeated part.' }
    : null;
  const valueSignature = valueType ? `value: ${valueType}` : null;
  return {
    ...part,
    valueProp,
    sharedProps: {
      react: valueSignature ? [valueSignature, ...SHARED_REACT_PART_PROPS] : [...SHARED_REACT_PART_PROPS],
      svelte: valueSignature ? [valueSignature, ...SHARED_SVELTE_PART_PROPS] : [...SHARED_SVELTE_PART_PROPS],
      solid: valueSignature ? [valueSignature, ...SHARED_SOLID_PART_PROPS] : [...SHARED_SOLID_PART_PROPS],
    },
  };
}

export const STYLED_COMPONENT_CATALOG = STYLED_COMPONENT_SEEDS.map((seed) => {
  const interactive = seed.implementationKind === 'interactive-controller';
  const rootProps = seed.rootProps.map((input) => ({
    name: input.name,
    reactive: true,
    required: input.required,
    type: input.type,
    defaultValue: input.defaultValue,
    description: `${input.required ? 'Required' : 'Optional'} reactive ${input.name} input from the canonical ${seed.name} contract.`,
  }));
  const parts = seed.parts.map((part) => hydratePart(
    part,
    (seed.partValueTypes as Readonly<Record<string, string>>)[part.id],
  ));
  return {
    id: seed.id,
    name: seed.name,
    inputs: rootProps.map(({ reactive: _reactive, ...input }) => input),
    implementationKind: seed.implementationKind,
    behaviorFamily: seed.behaviorFamily,
    api: {
      rootProps,
      callbacks: seed.callbacks,
      events: seed.events.map((event) => ({
        ...event,
        description: `${seed.name} semantic transition event ${event.type}.`,
      })),
      parts,
      ownership: {
        core: interactive
          ? `@uifn/core/${seed.id}: create${seed.name}Controller(props, environment?)`
          : `@uifn/core/${seed.id}: ${seed.name}Contract`,
        controllerType: interactive ? `${seed.name}Controller` : null,
        stateType: `${seed.name}State`,
        actionsType: interactive ? `${seed.name}Actions` : 'Record<string, never>',
        partsType: interactive ? `${seed.name}Controller["parts"]` : `${seed.name}ContractParts`,
        contexts: {
          react: `${seed.name}Provider and use${seed.name}(inputs); adapter context remains private`,
          svelte: `${seed.name}Provider; adapter context remains private to compound descendants`,
          solid: `${seed.name}Provider; adapter context remains private to compound descendants`,
        },
        dom: seed.domOwner,
      },
      dataAttributes: [
        { name: 'data-uifn-component', value: seed.id, parts: 'all styled parts', stability: 'stable' },
        { name: 'data-uifn-part', value: seed.parts.map((part) => part.id).join(' | '), parts: 'all styled parts', stability: 'stable' },
        ...seed.dataAttributes,
      ],
      cssVariables: [...SHARED_CSS_VARIABLES, ...seed.cssVariables]
        .sort((left, right) => left.name.localeCompare(right.name)),
      limitations: seed.limitations.map((limitation) => (
        limitation === 1 ? INTERACTIVE_LIMITATION : limitation === 0 ? STATIC_LIMITATION : limitation
      )),
    },
    parts: seed.parts,
    demo: seed.demo,
  };
});
export const STYLED_COMPONENT_COUNT = STYLED_COMPONENT_CATALOG.length;
export const STYLED_PART_COUNT = STYLED_COMPONENT_CATALOG.reduce((count, primitive) => count + primitive.parts.length, 0);
